<template>
  <section class="final-config-page">
    <header class="page-header">
      <div><div class="eyebrow"><span class="live-dot" /> FINAL CONFIG</div><h2>Final Config</h2><p>Tạo cấu hình cuối từ Memmap Payload đã được kiểm tra.</p></div>
      <el-button :icon="Refresh" :loading="loading" @click="fetchProfiles">Làm mới</el-button>
    </header>
    <el-alert v-if="errorMessage" class="load-alert" type="error" show-icon :title="errorMessage" @close="errorMessage = ''" />

    <el-tabs v-model="activeTab" class="final-tabs" @tab-change="handleTabChange">
      <el-tab-pane label="FINAL CONFIG MANAGER" name="manager">
        <el-card shadow="never"><template #header><div class="card-header"><span>Danh sách Final Config</span><el-input v-model="searchQuery" clearable placeholder="Tìm SKU, SO Number, Item Code..." style="width:300px" /></div></template>
          <div ref="profileTableEl" v-loading="loading" class="tabulator-host profile-table" />
        </el-card>
      </el-tab-pane>
      <el-tab-pane label="FINAL CONFIG CREATE" name="create">
        <el-card shadow="never"><template #header><span>Tạo Final Config</span></template>
          <el-form label-position="top" class="create-form">
            <el-row :gutter="16">
              <el-col :xs="24" :md="8"><el-form-item label="Sensor connectivity" required><el-select v-model="form.connectivity"><el-option label="LoRaWAN" value="LoRaWAN" /><el-option label="Sigfox" value="Sigfox" /></el-select></el-form-item></el-col>
              <el-col :xs="24" :md="8"><el-form-item label="SKU" required><el-input v-model="form.skuSuffix" :prefix-icon="null"><template #prepend>{{ skuPrefix }}</template></el-input></el-form-item></el-col>
              <el-col :xs="24" :md="8"><el-form-item label="LONG_FW (5FXXXX)" required :error="longFwError"><el-input v-model="form.longFw" maxlength="6" @input="normalizeLongFw" /></el-form-item></el-col>
            </el-row>
            <el-row :gutter="16"><el-col :xs="24" :md="12"><el-form-item label="SO_NUMBER" required :error="soError"><el-input v-model="form.soNumber" placeholder="SO/2026/12345" /></el-form-item></el-col><el-col :xs="24" :md="12"><el-form-item label="ITEM_CODE" required><el-input v-model="form.itemCode" placeholder="WSLRW-ATH-11" /></el-form-item></el-col></el-row>
          </el-form>
          <el-alert v-if="form.memmapId && !registers.length" title="Memmap Payload không có register hợp lệ từ địa chỉ 303 trở lên." type="warning" :closable="false" />
          <div v-if="registers.length" class="register-heading"><span><strong>{{ selectedCount }}</strong> / {{ registers.length }} registers được chọn</span><el-tag :type="hasInvalidSelected ? 'danger' : 'success'">{{ hasInvalidSelected ? 'Có cấu hình không hợp lệ' : 'Tất cả cấu hình đã chọn hợp lệ' }}</el-tag></div>
          <el-alert v-if="hasInvalidSelected" class="validation-alert" type="warning" :closable="false" show-icon :title="invalidSelectedMessage" />
          <div ref="registerTableEl" class="tabulator-host register-table" />
          <div class="actions"><el-button @click="resetCreate">Đặt lại</el-button><el-button type="primary" :loading="saving" :disabled="!canCreate" @click="createProfile">Create Final Config</el-button></div>
        </el-card>
      </el-tab-pane>
      <el-tab-pane label="FINAL CONFIG TOOL" name="tool">
        <FinalConfigTool />
      </el-tab-pane>
    </el-tabs>

    <el-dialog v-model="detailVisible" title="Chi tiết Final Config" width="90%" destroy-on-close><div v-loading="detailLoading"><div v-if="detail" class="details"><b>{{ detail.sku }}</b><span>SO: {{ detail.soNumber || detail.so_number }}</span><span>ITEM: {{ detail.itemCode || detail.item_code }}</span></div><div ref="detailTableEl" class="tabulator-host register-table" /></div></el-dialog>
  </section>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { Refresh } from '@element-plus/icons-vue';
import { TabulatorFull as Tabulator } from 'tabulator-tables';
import 'tabulator-tables/dist/css/tabulator.min.css';
import FinalConfigTool from '../components/FinalConfigTool.vue';
import { validateRegisterConfig } from '../utils/validator';

type Row = Record<string, any>;
const API = '/api/plugins/final-config'; const MEMMAP_API = '/api/plugins/memmap-manager';
const activeTab = ref('manager'), loading = ref(false), saving = ref(false), errorMessage = ref(''), searchQuery = ref('');
const profiles = ref<Row[]>([]), memmapProfiles = ref<Row[]>([]), registers = ref<Row[]>([]), detail = ref<Row | null>(null), detailVisible = ref(false), detailLoading = ref(false);
const form = ref({ connectivity: 'LoRaWAN', skuSuffix: '', longFw: '', soNumber: '', itemCode: '', memmapId: '' });
const profileTableEl = ref<HTMLElement>(), registerTableEl = ref<HTMLElement>(), detailTableEl = ref<HTMLElement>(); let profileTable: Tabulator | undefined, registerTable: Tabulator | undefined, detailTable: Tabulator | undefined;
const skuPrefix = computed(() => form.value.connectivity === 'Sigfox' ? 'WSSFC-' : 'WSLRW-'); const sku = computed(() => `${skuPrefix.value}${form.value.skuSuffix.trim()}`); const shortFw = computed(() => /^5F[A-Z0-9]{4}$/.test(form.value.longFw) ? form.value.longFw.charAt(0) : '');
const longFwError = computed(() => form.value.longFw && !/^5F[A-Z0-9]{4}$/.test(form.value.longFw) ? 'LONG_FW phải đúng mẫu 5FXXXX.' : ''); const soError = computed(() => form.value.soNumber && !/^SO\/\d{4}\/\d{5}$/.test(form.value.soNumber) ? 'SO_NUMBER phải đúng mẫu SO/2026/12345.' : '');
const selectedCount = computed(() => registers.value.filter(r => r.selected).length); const hasInvalidSelected = computed(() => registers.value.some(r => r.selected && r.configCheck === 'FAIL')); const invalidSelectedMessage = computed(() => registers.value.find(r => r.selected && r.configCheck === 'FAIL')?.configError || 'Có register được chọn có cấu hình không hợp lệ.');
const canCreate = computed(() => Boolean(sku.value && shortFw.value && /^SO\/\d{4}\/\d{5}$/.test(form.value.soNumber) && form.value.itemCode.trim() && form.value.memmapId && registers.value.length && selectedCount.value && !hasInvalidSelected.value));
function val(row: Row | undefined | null, ...keys: string[]) { if (!row) return ''; const hit = keys.map(k => row[k]).find(v => v !== undefined && v !== null && v !== ''); return hit !== undefined ? hit : ''; }
function normalizeLongFw() { form.value.longFw = form.value.longFw.toUpperCase().replace(/\s/g, ''); }
async function request<T>(base: string, endpoint: string, options: RequestInit = {}): Promise<T> { const headers = new Headers(options.headers || {}); headers.set('Content-Type', 'application/json'); const token = localStorage.getItem('itest_token') || localStorage.getItem('token') || sessionStorage.getItem('token'); if (token) headers.set('Authorization', `Bearer ${token}`); const res = await fetch(`${base}${endpoint}`, { ...options, headers }); if (!res.ok) { const body = await res.json().catch(() => ({})); throw new Error(body.message || `Lỗi yêu cầu: ${res.status}`); } return res.json(); }
function destroy(t?: Tabulator | null) { if (t) { try { t.destroy(); } catch (e) { console.warn('Destroy table error:', e); } } }
function profileColumns(withActions = true) { const columns: any[] = [{ title: 'SKU', field: 'sku', minWidth: 170 }, { title: 'SO Number', field: 'soNumber', minWidth: 150, formatter: (c: any) => val(c.getRow()?.getData(), 'soNumber', 'so_number') || '—' }, { title: 'Item Code', field: 'itemCode', minWidth: 160, formatter: (c: any) => val(c.getRow()?.getData(), 'itemCode', 'item_code') || '—' }, { title: 'Connectivity', field: 'connectivity', width: 125 }, { title: 'LONG_FW', field: 'longFw', width: 115, formatter: (c: any) => val(c.getRow()?.getData(), 'longFw', 'long_fw') || '—' }, { title: 'Registers', field: 'registersCount', width: 105, formatter: (c: any) => String(val(c.getRow()?.getData(), 'registersCount', 'registers_count') || 0) }, { title: 'Created by', field: 'createdBy', width: 140, formatter: (c: any) => val(c.getRow()?.getData(), 'createdBy', 'created_by') || '—' }]; return columns; }
function renderProfiles() { destroy(profileTable); profileTable = undefined; if (!profileTableEl.value) return; try { profileTable = new Tabulator(profileTableEl.value, { data: profiles.value, layout: 'fitColumns', placeholder: 'Chưa có Final Config nào.', columns: profileColumns() as any, rowDblClick: (_e: Event, row: any) => { const d = row.getData(); if (d?.id) viewProfile(String(d.id)); }, rowContextMenu: [{ label: 'Xem chi tiết', action: (_e: Event, row: any) => { const d = row.getData(); if (d?.id) viewProfile(String(d.id)); } }, { label: 'Xóa Final Config', action: (_e: Event, row: any) => { const d = row.getData(); if (d) removeProfile(d); } }] }); profileTable.on('tableBuilt', () => { if (searchQuery.value.trim()) filterProfiles(); }); } catch (e) { console.error('Failed to init profileTable:', e); } }
function registerColumns(editable: boolean) { const selectionColumn = editable ? [{ formatter: 'rowSelection', titleFormatter: 'rowSelection', width: 42, hozAlign: 'center', headerSort: false }] : []; return [...selectionColumn, { title: 'Dec address', field: 'modbusRegisterDec', width: 105 }, { title: 'Hex address', field: 'modbusRegisterHex', width: 105 }, { title: 'Nums Reg', field: 'registerCount', width: 88 }, { title: 'Description', field: 'description', minWidth: 150, widthGrow: 2 }, { title: 'Format', field: 'format', width: 90 }, { title: 'Comment', field: 'comment', minWidth: 125, widthGrow: 1 }, { title: 'End-user Default', field: 'endUserDefault', minWidth: 130, widthGrow: 1 }, { title: 'Input config', field: 'inputConfig', minWidth: 130, widthGrow: 1, editor: editable ? 'input' : false, cellEdited: (cell: any) => updateConfig(cell.getRow()) }, { title: 'Check', field: 'configCheck', width: 80, formatter: (cell: any) => `<span class="check-${cell.getValue() === 'PASS' ? 'pass' : 'fail'}">${cell.getValue()}</span>` }] as any[]; }
function renderRegisters() { destroy(registerTable); registerTable = undefined; if (!registerTableEl.value) return; try { registerTable = new Tabulator(registerTableEl.value, { data: registers.value, layout: 'fitColumns', height: '460px', selectableRows: true, selectableRowsPersistence: false, columns: registerColumns(true) as any, rowSelectionChanged: (selected: any[]) => { const selectedRows = new Set(selected.map((row: any) => row.getData())); registers.value.forEach(item => { item.selected = selectedRows.has(item); }); }, rowFormatter: (row: any) => { const d = row.getData(); if (d) row.getElement().classList.toggle('invalid-row', d.configCheck === 'FAIL' && d.selected); } }); registerTable.on('tableBuilt', () => { try { registerTable?.getRows().forEach((row: any) => { if (row?.getData()?.selected) row.select(); }); } catch (e) {} }); } catch (e) { console.error('Failed to init registerTable:', e); } }
function updateConfig(row: any) { const data = row.getData(); if (!data) return; const inputConfig = String(data.inputConfig ?? ''); const normalized = String(data.format || '').trim().toLowerCase() === 'hex' ? inputConfig.replace(/\s+/g, '').toUpperCase() : inputConfig.trim(); const result = validateRegisterConfig(normalized, data.format, Number(data.registerCount)); row.update({ inputConfig: normalized, configCheck: result.valid ? 'PASS' : 'FAIL', configError: result.error || '' }); row.getElement().classList.toggle('invalid-row', Boolean(data.selected) && !result.valid); }
async function fetchProfiles() { loading.value = true; errorMessage.value = ''; try { const [finalRows, maps] = await Promise.all([request<unknown>(API, '/profiles'), request<unknown>(MEMMAP_API, '/profiles')]); profiles.value = Array.isArray(finalRows) ? finalRows as Row[] : []; memmapProfiles.value = Array.isArray(maps) ? maps as Row[] : []; await nextTick(); renderProfiles(); } catch (e) { errorMessage.value = e instanceof Error ? e.message : 'Không thể tải dữ liệu Final Config'; } finally { loading.value = false; } }
async function loadMemmap() { registers.value = []; destroy(registerTable); registerTable = undefined; if (!form.value.memmapId) return; try { const source = await request<Row>(MEMMAP_API, `/profiles/${form.value.memmapId}`); registers.value = (source.registers || []).map((r: Row, index: number) => { const dec = Number(val(r, 'modbusRegisterDecimal', 'modbusRegisterDec', 'modbus_register_dec', 'address')); const description = String(val(r, 'description', 'name') || ''); const format = String(val(r, 'format', 'dataType') || ''); const sourceDefault = val(r, 'endUserDefault', 'end_user_default', 'defaultValue'); const inputConfig = ''; const count = Number(val(r, 'registerCount', 'numRegisters', 'num_registers') || 1); const check = validateRegisterConfig(inputConfig, format, count); return { rowNumber: Number(val(r, 'rowNumber', 'row_number') || index + 1), modbusRegisterDec: dec, modbusRegisterHex: val(r, 'modbusRegisterHex', 'modbus_register_hex', 'hex') || '', registerCount: count, description, format, comment: val(r, 'comment') || '', endUserDefault: sourceDefault ?? '', inputConfig, selected: !/spare/i.test(description), configCheck: check.valid ? 'PASS' : 'FAIL', configError: check.error || '' }; }).filter(r => Number.isFinite(r.modbusRegisterDec) && r.modbusRegisterDec >= 303).sort((a, b) => a.modbusRegisterDec - b.modbusRegisterDec); await nextTick(); renderRegisters(); } catch (e) { ElMessage.error(e instanceof Error ? e.message : 'Không thể đọc Memmap Payload'); } }
function matchMemmap() { const longFw = form.value.longFw.trim().toUpperCase(); if (!sku.value || !/^5F[A-Z0-9]{4}$/.test(longFw)) { form.value.memmapId = ''; registers.value = []; destroy(registerTable); registerTable = undefined; return; } const match = memmapProfiles.value.find(profile => String(val(profile, 'sku')).trim().toUpperCase() === sku.value.toUpperCase() && String(val(profile, 'longFw', 'long_fw')).trim().toUpperCase() === longFw); form.value.memmapId = match ? String(match.id) : ''; if (match) void loadMemmap(); else { registers.value = []; destroy(registerTable); registerTable = undefined; } }
async function createProfile() { if (!canCreate.value) return; saving.value = true; try { const payload = { connectivity: form.value.connectivity, sku: sku.value, longFw: form.value.longFw, shortFw: shortFw.value, soNumber: form.value.soNumber, itemCode: form.value.itemCode.trim(), registers: registers.value.map(r => ({ rowNumber: r.rowNumber, modbusRegisterDec: r.modbusRegisterDec, modbusRegisterHex: r.modbusRegisterHex, registerCount: r.registerCount, description: r.description, format: r.format, comment: r.comment, endUserDefault: r.endUserDefault, inputConfig: r.inputConfig, configCheck: r.configCheck, selected: r.selected })) }; await request(API, '/profiles', { method: 'POST', body: JSON.stringify(payload) }); ElMessage.success('Đã tạo Final Config'); resetCreate(); activeTab.value = 'manager'; await fetchProfiles(); } catch (e) { ElMessage.error(e instanceof Error ? e.message : 'Không thể tạo Final Config'); } finally { saving.value = false; } }
function resetCreate() { form.value = { connectivity: 'LoRaWAN', skuSuffix: '', longFw: '', soNumber: '', itemCode: '', memmapId: '' }; registers.value = []; destroy(registerTable); registerTable = undefined; }
async function viewProfile(id: string) { detailVisible.value = true; detailLoading.value = true; detail.value = null; try { detail.value = await request<Row>(API, `/profiles/${id}`); await nextTick(); destroy(detailTable); detailTable = undefined; if (detailTableEl.value && detail.value) { detailTable = new Tabulator(detailTableEl.value, { data: detail.value.registers || [], layout: 'fitDataStretch', height: '430px', columns: registerColumns(false) as any }); } } catch (e) { ElMessage.error(e instanceof Error ? e.message : 'Không thể tải chi tiết'); detailVisible.value = false; } finally { detailLoading.value = false; } }
async function removeProfile(profile: Row) { try { await ElMessageBox.confirm(`Xóa Final Config ${profile.sku}? Thao tác không thể hoàn tác.`, 'Xác nhận xóa', { type: 'warning' }); await request(API, `/profiles/${profile.id}`, { method: 'DELETE' }); ElMessage.success('Đã xóa Final Config'); await fetchProfiles(); } catch (e) { if (e !== 'cancel' && e !== 'close') ElMessage.error(e instanceof Error ? e.message : 'Không thể xóa Final Config'); } }
function filterProfiles() { const q = searchQuery.value.trim().toLowerCase(); if (!profileTable) return; try { if (q) { profileTable.setFilter((data: any) => { if (!data) return false; try { return JSON.stringify(data).toLowerCase().includes(q); } catch { return false; } }); } else { profileTable.clearFilter(); } } catch (e) { console.warn('Filter error:', e); } }
function handleTabChange(tab: string | number) { if (tab === 'manager') void fetchProfiles(); }
watch(searchQuery, filterProfiles); watch([sku, () => form.value.longFw, memmapProfiles], matchMemmap); onMounted(fetchProfiles); onBeforeUnmount(() => { destroy(profileTable); destroy(registerTable); destroy(detailTable); });
</script>

<style scoped>
.final-config-page{display:flex;flex-direction:column;gap:16px}.page-header,.card-header,.register-heading,.actions,.details{display:flex;align-items:center;gap:12px}.page-header,.card-header,.register-heading{justify-content:space-between}.eyebrow{font-size:11px;font-weight:700;letter-spacing:.1em;color:#0284c7}.live-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#0284c7;margin-right:7px}.page-header h2{margin:4px 0;font-size:22px;color:#0f172a}.page-header p{margin:0;color:#64748b;font-size:13px}.create-form{margin-bottom:12px}.tabulator-host{width:100%}.profile-table{min-height:150px}.register-table{margin-top:14px;border:1px solid #dbe4ef;border-radius:6px;overflow:hidden}.register-heading{margin-top:16px;font-size:13px;color:#475569}.actions{justify-content:flex-end;margin-top:16px}.details{padding:0 0 14px;flex-wrap:wrap;color:#475569}:deep(.tabulator){font-size:12px;border:0}:deep(.tabulator .tabulator-header){background:#f1f5f9}:deep(.tabulator .tabulator-row.tabulator-selected),:deep(.tabulator .tabulator-row.tabulator-selected:hover){background:inherit;color:inherit}:deep(.tabulator .tabulator-row.invalid-row){background:#fee2e2}:deep(.check-pass){color:#059669;font-weight:700}:deep(.check-fail){color:#dc2626;font-weight:700}@media(max-width:720px){.page-header,.card-header,.register-heading{flex-direction:column;align-items:stretch}}
</style>
